@Composable internal fun ProvidePlayerGlassPalette(playerViewModel: PlayerViewModel, content: @Composable () -> Unit) {
    if (!LocalGlassModeEnabled.current) { content(); return }
    val isDark = LocalPixelPlayDarkTheme.current
    val pair by playerViewModel.activePlayerColorSchemePair.collectAsStateWithLifecycle()
    val accent = GlassPalette.playerAccent(pair?.let { if (isDark) it.dark else it.light }?.primary, MaterialTheme.colorScheme.primary)
